// Seeds the demo: class 9B with Riya and Kabir (the two demo students) plus
// 29 simulated classmates. Classmates' history is generated by running the
// real engine against simulated students, which also warms up the Elo
// ratings of every question (cold-start safeguard 4).

import { CONCEPTS } from '../data/concepts.js';
import { questionsFor } from '../data/questions.js';
import { createStudent, recordAnswer } from './student.js';
import { makeSimStudent, rng } from './sim.js';

const NAMES = [
  'Aarav', 'Ananya', 'Ishaan', 'Diya', 'Vihaan', 'Saanvi', 'Arjun', 'Meera', 'Sameer', 'Priya',
  'Rohan', 'Sneha', 'Aditya', 'Pooja', 'Kunal', 'Neha', 'Siddharth', 'Lavanya', 'Yash', 'Tanvi',
  'Harsh', 'Fatima', 'Manav', 'Ritika', 'Om', 'Zoya', 'Dev', 'Kavya', 'Nikhil',
];

const DAY = 24 * 60 * 60 * 1000;

export function seedDemo(now = Date.now()) {
  const rand = rng(2026);
  const qstats = {};
  const students = {};

  // Classmates: about half share a Class 6 negative-numbers gap (the story the
  // teacher brief should surface), others have different or no gaps.
  NAMES.forEach((name, i) => {
    const r = rand();
    const roots = r < 0.55 ? ['c6_int'] : r < 0.68 ? ['c6_frac'] : r < 0.76 ? ['c6_var'] : r < 0.84 ? ['c7_expr'] : [];
    const sim = makeSimStudent(roots, rand);
    const s = createStudent({
      id: `s${i + 1}`, name, grade: 9,
      mastery: Object.fromEntries(CONCEPTS.map((c) => [c.id, 0.5])),
    });
    // 4 answers per concept (48 in all), spread over the past two weeks
    let k = 0;
    for (let round = 0; round < 4; round++) {
      for (const c of CONCEPTS) {
        const pool = questionsFor(c.id);
        const q = pool[Math.floor(rand() * pool.length)];
        const t = now - (14 - k * 0.28) * DAY;
        recordAnswer(s, qstats, q.id, sim.answer(q).id, { now: t, mode: 'seed' });
        k++;
      }
    }
    // A couple of students have gone quiet (for the "alerts" panel)
    if (i === 6 || i === 19) s.lastActive = now - 7 * DAY;
    students[s.id] = s;
  });

  // Riya — Class 9, behind on basics (the demo story): weak on negatives.
  students.riya = createStudent({
    id: 'riya', name: 'Riya', grade: 9, lang: 'hi',
    mastery: {
      c6_int: 0.38, c6_frac: 0.9, c6_var: 0.9,
      c7_intops: 0.45, c7_intmul: 0.5, c7_fracops: 0.88, c7_expr: 0.55,
      c7_simpleeq: 0.55, c8_lineq: 0.5, c8_brackets: 0.5, c9_poly: 0.45, c9_lin2: 0.4,
    },
  });
  // Kabir — Class 9, ahead and bored: everything strong, ready to stretch / teach Chotu.
  students.kabir = createStudent({
    id: 'kabir', name: 'Kabir', grade: 9, lang: 'en',
    mastery: Object.fromEntries(CONCEPTS.map((c) => [c.id, c.grade <= 8 ? 0.93 : 0.7])),
  });

  return {
    version: 1,
    students,
    qstats,
    classFocus: null,        // teacher override for the whole class
    briefApproved: false,
    rubricEdits: {},
    seededAt: now,
  };
}
